import sys

def main():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    if len(lines) < 3:
        return
    a = int(lines[0])
    b = int(lines[1])
    op = lines[2]
    if op == '+':
        res = a + b
    elif op == '-':
        res = a - b
    elif op == '*':
        res = a * b
    elif op == '/':
        if b == 0:
            res = 0
        else:
            res = int(a / b)
    else:
        res = 0
    print(res)

if __name__ == "__main__":
    main()
